// aim.cpp
// World-to-screen projection + smoothed crosshair delta inside a 240 px cone.
//
// Build (standalone smoke test):
//   cl /EHsc /std:c++17 /DAIM_SMOKE aim.cpp /Fe:aim_test.exe
//
// Exported helpers (all in the global namespace):
//   bool  W2S(const Vec3& world, const float viewMatrix[16], float sw, float sh, Vec2& out)
//       -- projects a world-space point through a column-major view-projection matrix;
//          returns false when the point is behind the near plane.
//
//   Vec2  AimDelta(Vec2 current, Vec2 target, float smoothing, float coneRadiusPx)
//       -- returns the per-frame crosshair nudge toward `target` from `current`,
//          clamped to `coneRadiusPx` = 240 px; zero vector when target is outside the cone.
//
//   Vec2  BestTarget(const Vec3* headPositions, int count,
//                    const float viewMatrix[16], float sw, float sh,
//                    Vec2 crosshair, float coneRadiusPx)
//       -- iterates an entity head array, projects each head, and returns the
//          screen-space position of the closest one inside the cone.

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <cmath>
#include <cfloat>

// ---------------------------------------------------------------------------
// Math primitives
// ---------------------------------------------------------------------------

struct Vec2 {
    float x, y;
    Vec2() : x(0.f), y(0.f) {}
    Vec2(float x, float y) : x(x), y(y) {}
    Vec2 operator+(const Vec2& o) const { return {x + o.x, y + o.y}; }
    Vec2 operator-(const Vec2& o) const { return {x - o.x, y - o.y}; }
    Vec2 operator*(float s)        const { return {x * s,   y * s};   }
    float Dot(const Vec2& o)       const { return x * o.x + y * o.y;  }
    float LengthSq()               const { return x * x + y * y;      }
    float Length()                 const { return sqrtf(LengthSq());   }
};

struct Vec3 {
    float x, y, z;
    Vec3() : x(0.f), y(0.f), z(0.f) {}
    Vec3(float x, float y, float z) : x(x), y(y), z(z) {}
};

// ---------------------------------------------------------------------------
// W2S
// ---------------------------------------------------------------------------
// viewMatrix is a column-major 4x4 view-projection matrix (OpenGL / D3D row-
// major row-vector convention both work as long as the caller is consistent).
// Returns false when w <= 0 (behind near plane); screen origin is top-left.

bool W2S(const Vec3& world, const float vm[16], float sw, float sh, Vec2& out)
{
    // Transform to clip space: v' = vm * [wx, wy, wz, 1]^T
    // Column-major layout: vm[col*4 + row]
    float clipX = vm[0]*world.x + vm[4]*world.y + vm[8]*world.z  + vm[12];
    float clipY = vm[1]*world.x + vm[5]*world.y + vm[9]*world.z  + vm[13];
    // float clipZ = vm[2]*world.x + vm[6]*world.y + vm[10]*world.z + vm[14]; // unused
    float clipW = vm[3]*world.x + vm[7]*world.y + vm[11]*world.z + vm[15];

    if (clipW <= 0.f)
        return false;

    float invW = 1.f / clipW;
    float ndcX =  clipX * invW;  // [-1, 1]
    float ndcY = -clipY * invW;  // flip Y: NDC +Y → screen top

    out.x = (ndcX + 1.f) * 0.5f * sw;
    out.y = (ndcY + 1.f) * 0.5f * sh;
    return true;
}

// ---------------------------------------------------------------------------
// AimDelta
// ---------------------------------------------------------------------------
// Returns the frame delta to nudge `current` toward `target`.
//
//   smoothing      – value in (0, 1]; 1.0 = instant snap, 0.05 = very smooth.
//   coneRadiusPx   – targets farther than this many pixels from `current` are
//                    ignored (returns zero vector).  Pass 240.f for a 240 px cone.

Vec2 AimDelta(Vec2 current, Vec2 target, float smoothing, float coneRadiusPx)
{
    Vec2  delta = target - current;
    float dist  = delta.Length();

    if (dist < 0.5f || dist > coneRadiusPx)
        return Vec2(0.f, 0.f);

    // Clamp smoothing to a safe range so we never overshoot.
    if (smoothing < 0.001f) smoothing = 0.001f;
    if (smoothing > 1.f)    smoothing = 1.f;

    return delta * smoothing;
}

// ---------------------------------------------------------------------------
// BestTarget
// ---------------------------------------------------------------------------
// Scans `count` world-space head positions, projects each with W2S, and
// returns the screen position of the head closest to `crosshair` that falls
// inside `coneRadiusPx`.  Returns the crosshair position unchanged (and sets
// *outFound = false if provided) when no valid target exists.

Vec2 BestTarget(const Vec3* headPositions, int count,
                const float viewMatrix[16], float sw, float sh,
                Vec2 crosshair, float coneRadiusPx,
                bool* outFound = nullptr)
{
    float bestDistSq = coneRadiusPx * coneRadiusPx;
    Vec2  bestScreen = crosshair;
    bool  found      = false;

    for (int i = 0; i < count; ++i) {
        Vec2 screen;
        if (!W2S(headPositions[i], viewMatrix, sw, sh, screen))
            continue;

        Vec2  d      = screen - crosshair;
        float distSq = d.LengthSq();

        if (distSq < bestDistSq) {
            bestDistSq = distSq;
            bestScreen = screen;
            found      = true;
        }
    }

    if (outFound) *outFound = found;
    return bestScreen;
}

// ---------------------------------------------------------------------------
// Smoke test (compiled only with /DAIM_SMOKE)
// ---------------------------------------------------------------------------
#ifdef AIM_SMOKE
#include <cstdio>

int main()
{
    // Minimal orthographic-ish projection matrix (identity-ish, D3D style).
    // Real usage passes the game's view-projection matrix.
    float vm[16] = {
        1.f, 0.f, 0.f, 0.f,
        0.f, 1.f, 0.f, 0.f,
        0.f, 0.f, 1.f, 0.f,
        0.f, 0.f, 0.f, 1.f
    };

    const float SW = 1920.f, SH = 1080.f;
    Vec2 crosshair(SW * 0.5f, SH * 0.5f);

    // --- W2S smoke ---
    Vec3 worldPt(0.f, 0.f, 0.f);   // maps to NDC (0,0) → screen centre
    Vec2 screenPt;
    bool ok = W2S(worldPt, vm, SW, SH, screenPt);
    printf("W2S: ok=%d  screen=(%.1f, %.1f)  expected=(%.1f, %.1f)\n",
           ok, screenPt.x, screenPt.y, SW * 0.5f, SH * 0.5f);

    // --- AimDelta smoke: target inside cone ---
    Vec2 target(crosshair.x + 100.f, crosshair.y + 50.f);
    Vec2 delta = AimDelta(crosshair, target, 0.1f, 240.f);
    printf("AimDelta inside cone:  delta=(%.2f, %.2f)\n", delta.x, delta.y);

    // --- AimDelta smoke: target outside cone ---
    Vec2 farTarget(crosshair.x + 500.f, crosshair.y);
    Vec2 zeroDelta = AimDelta(crosshair, farTarget, 0.1f, 240.f);
    printf("AimDelta outside cone: delta=(%.2f, %.2f)  expected=(0.00, 0.00)\n",
           zeroDelta.x, zeroDelta.y);

    // --- BestTarget smoke ---
    Vec3 heads[3] = {
        Vec3( 0.1f,  0.05f, 0.f),   // near centre → projects near crosshair
        Vec3( 0.9f,  0.5f,  0.f),   // far right
        Vec3(-0.9f, -0.5f,  0.f),   // far left
    };
    bool found = false;
    Vec2 best = BestTarget(heads, 3, vm, SW, SH, crosshair, 240.f, &found);
    printf("BestTarget: found=%d  screen=(%.1f, %.1f)\n", found, best.x, best.y);

    return 0;
}
#endif // AIM_SMOKE
